import React from 'react';
import styled from 'styled-components';
import { mediaSrc } from './Markdown';

// Turns whatever an editor pasted (share link, short link, edit link or the
// whole <iframe> embed code) into an embeddable Google Forms URL, or '' if it
// isn't a Google Form. Keep in step with googleFormSrc in static/admin/index.html.
export const googleFormSrc = (input) => {
  const match = String(input || '').match(/https:\/\/(?:docs\.google\.com\/forms\/[^\s"'<>]+|forms\.gle\/[\w-]+)/);
  if (!match) return '';
  let src = match[0].replace(/&amp;/g, '&');
  if (src.startsWith('https://docs.google.com/')) {
    src = src.replace(/\/edit(?:[?#].*)?$/, '/viewform');
    if (!/[?&]embedded=true/.test(src)) src += `${src.includes('?') ? '&' : '?'}embedded=true`;
  }
  return src;
};

export const formHeight = (height) => Math.min(5000, Math.max(300, parseInt(height, 10) || 1000));

const Media = styled.div`
  margin: 40px 0;

  figure {
    margin: 0 0 32px;
  }

  img {
    display: block;
    max-width: 100%;
    height: auto;
  }

  figcaption {
    margin-top: 8px;
    font-size: 16px;
    color: #00000099;
  }

  iframe {
    display: block;
    width: 100%;
    border: 0;
    margin-bottom: 32px;
  }
`;

// The CMS "Media (end of page)" list: images, GIFs and Google Forms.
const MediaSection = ({ media, base }) => {
  if (!media || !media.length) return null;

  return (
    <Media>
      {media.map((item, i) => {
        if (!item) return null;
        if (item.type === 'form') {
          const src = googleFormSrc(item.url);
          return src && <iframe key={i} src={src} height={formHeight(item.height)} title="Google Form" loading="lazy" />;
        }
        return (
          item.src && (
            <figure key={i}>
              <img src={mediaSrc(item.src, base)} alt={item.alt || ''} loading="lazy" decoding="async" />
              {item.caption && <figcaption>{item.caption}</figcaption>}
            </figure>
          )
        );
      })}
    </Media>
  );
};

export default MediaSection;
